    $code := $uppercase(countryCode);
    $year := year > 0 ? year : $number($substring($now(), 0, 4));
    $code in $covered
        ? {"url": "https://date.nager.at/api/v3/PublicHolidays/" & $string($year) & "/" & $code, "dataType": "json"}
        : $error("Nager.Date has no public holidays for the country asked about (country code " & $code & "). It covers " & $string($count($covered)) & " countries.")
)

